#include <Arduino.h>
#include <TM1637Display.h>

TM1637Display display(4, 5);
struct Button {
  uint8_t pin;
  bool raw;
  bool stable;
  unsigned long changed;
};
Button up = {2, HIGH, HIGH, 0};
Button down = {3, HIGH, HIGH, 0};
int countValue = 0;
bool locked = false;
bool resetDone = false;
unsigned long downSince = 0;

bool updateButton(Button &b, unsigned long now) {
  bool level = digitalRead(b.pin);
  if (level != b.raw) {
    b.raw = level;
    b.changed = now;
  }
  if (b.stable != b.raw && now - b.changed >= 30) {
    b.stable = b.raw;
    return true;
  }
  return false;
}

void render() {
  display.showNumberDec(countValue, false);
  digitalWrite(13, countValue % 2 == 0 ? HIGH : LOW);
  if (locked) tone(6, 1000);
  else noTone(6);
}

void setup() {
  pinMode(2, INPUT_PULLUP);
  pinMode(3, INPUT_PULLUP);
  pinMode(13, OUTPUT);
  pinMode(6, OUTPUT);
  display.setBrightness(7);
  render();
}

void loop() {
  unsigned long now = millis();
  bool upChanged = updateButton(up, now);
  bool downChanged = updateButton(down, now);
  bool dirty = false;
  if (upChanged && up.stable == LOW && !locked) {
    ++countValue;
    if (countValue == 15) locked = true;
    dirty = true;
  }
  if (downChanged) {
    if (down.stable == LOW) {
      downSince = now;
      resetDone = false;
      if (!locked) {
        --countValue;
        dirty = true;
      }
    } else {
      resetDone = false;
    }
  }
  if (locked && down.stable == LOW && !resetDone && now - downSince >= 2000) {
    countValue = 0;
    locked = false;
    resetDone = true;
    dirty = true;
  }
  if (dirty) render();
}
